const src = $('Prepare Send').item.json;
const bin = $input.item.binary;
const pdfOk = !!(bin && bin.data);
// CustomJS names the raw response after its own endpoint ("html2pdf") — give
// the attachment a real filename before it reaches Gmail instead.
const companySlug = (src.client && src.client.companyName ? src.client.companyName : 'Proposal')
  .replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'Proposal';
const fileName = `TrueTel-Cloud-Phone-Proposal-${companySlug}.pdf`;
// This n8n instance stores binary data on disk ("filesystem" mode), where
// bin.data.data is not reliably the resolved base64 string — getBinaryDataBuffer
// is the storage-mode-agnostic way to actually read it. SignWell needs a real
// base64 string in its request body (not a binary property), so it's resolved
// here once rather than trusting a raw expression later.
const pdfBase64 = pdfOk ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('base64') : null;
return [{
  json: { ...src, pdfOk, pdfBase64 },
  binary: pdfOk ? { data: { ...bin.data, fileName, fileExtension: 'pdf', mimeType: 'application/pdf' } } : undefined,
}];

const { pdfBase64, ...src } = $('PDF Generated OK?').item.json; // drop the base64 blob now that SignWell's had it — no need to carry it through every downstream node's data
const bin = $('PDF Generated OK?').item.binary;
const ok = !!($json && $json.id && Array.isArray($json.recipients) && $json.recipients[0]);
const signingUrl = ok ? $json.recipients[0].signing_url : null;
return [{ json: { ...src, signWellOk: ok && !!signingUrl, signingUrl }, binary: bin }];

return [{ json: {
  locationId: "PASTE_GHL_LOCATION_ID_HERE", // GHL sub-account (Settings -> Business Info)
  pipelineId: "PASTE_GHL_PIPELINE_ID_HERE", // e.g. the "01 - BDM - Jack - Felix" pipeline
  proposalSentStageId: "PASTE_PROPOSAL_SENT_STAGE_ID_HERE", // e.g. "Proposal Sent - Awaiting Responses"
} }];

const src = $('Prepare Send').item.json;
const hasPhone = !!(src.client && src.client.contactPhone && src.client.contactPhone.trim());
const list = $json.contacts || $json.data || (Array.isArray($json) ? $json : []);
const match = hasPhone && Array.isArray(list) ? list[0] : null;
return [{ json: { ...src, ghlContactId: match ? (match.id || match._id || null) : null } }];

const src = $('GHL - Check Found by Phone').item.json;
const list = $json.contacts || $json.data || (Array.isArray($json) ? $json : []);
const match = Array.isArray(list) ? list[0] : null;
return [{ json: { ...src, ghlContactId: match ? (match.id || match._id || null) : null } }];

const src = $('GHL - Check Found by Email').item.json;
const contact = $json.contact || $json;
return [{ json: { ...src, ghlContactId: contact.id || contact.contactId || null } }];

const src = $('GHL - Contact Resolved').item.json;
const list = $json.opportunities || $json.data || (Array.isArray($json) ? $json : []);
const openOne = Array.isArray(list) ? (list.find((o) => o.status === 'open') || list[0]) : null;
return [{ json: { ...src, ghlOpportunityId: openOne ? (openOne.id || openOne._id || null) : null } }];

