,"img":"https://m.media-amazon.com/images/I/51WiNRCHtAL._AC_SL1318_.jpg","features":["7\" Touch Screen","Android 9.0 OS","5MP Adjustable Camera","Cool Lighting Keypad"]},"gs_basic":{"title":"Grandstream GRP2604P","subtitle":"Basic / Essential","img":"https://m.media-amazon.com/images/I/71rhsedj9JL._AC_SL1500_.jpg","features":["132x64 Backlit LCD","3 Lines / 6 SIP Accounts","Gigabit Ports","PoE Support"]},"gs_medium":{"title":"Grandstream GRP2615","subtitle":"Medium / High-End","img":"https://m.media-amazon.com/images/I/519O05T4fmL._AC_SL1200_.jpg","features":["4.3\" Color LCD","10 Lines / 16 SIP Accounts","Integrated Wi-Fi/BT","40 Virtual BLF Keys"]},"gs_premium":{"title":"Grandstream GXV3380","subtitle":"Premium Video Phone","img":"https://m.media-amazon.com/images/I/51OxZwzvqzL._AC_SL1500_.jpg","features":["8\" Touch Screen","Android OS","2MP Camera","HDMI In/Out"]},"headset_wh67":{"title":"Yealink WH67 DECT Wireless Headset","subtitle":"Convertible UC Bluetooth/DECT","img":"https://m.media-amazon.com/images/I/71+zmCs37VL._AC_SL1500_.jpg","features":["DECT + Bluetooth (120m range)","4\" Touchscreen Base","Dual Mics, Noise Filtering","~8 hrs Talk Time"]},"net_ap_tplink":{"title":"TP-Link Omada AX3000","subtitle":"Basic Access Point","img":"https://m.media-amazon.com/images/I/41OrxU-z1nL._AC_SL1000_.jpg","features":["Wi-Fi 6 (AX3000)","Gigabit PoE Port","Seamless Roaming","Cloud Management"]},"net_extender_cisco":{"title":"Cisco Business CBW142ACM","subtitle":"Wi-Fi Mesh Extender","img":"https://m.media-amazon.com/images/I/61CIvpNXJwL._AC_SX569_.jpg","features":["Seamless Roaming","Plug-and-Play Deployment","Compact Wall-Mount","Enterprise Security"]},"net_switch":{"title":"Cisco Business CBS220-8P-E-2G","subtitle":"Managed PoE+ Switch","img":"https://m.media-amazon.com/images/I/51PrengxL8L._AC_SL1500_.jpg","features":["8x Gigabit PoE+ Ports","VLAN & QoS Support","Fanless, Silent","Compact Design"]},"net_router":{"title":"Cisco RV340 VPN Router","subtitle":"Business Security Gateway","img":"https://m.media-amazon.com/images/I/71NMLNv+WiL._AC_SL1500_.jpg","features":["Dual Gigabit WAN/LAN","Site-to-Site & Remote VPN","Built-in Firewall","Reliable Connectivity"]}};
const body = $json.body;
const cs = body.currentSetup;
const isMultiSite = body.dealShape === 'multiSite';
const siteCount = Math.max(1, body.quantities?.siteCount || 1);

const scenarioType = cs.hasProvider ? 'switching' : 'newInstall';
let scenarioLabel = cs.hasProvider
  ? 'Current Environment vs. TrueTel Recommendation'
  : 'Your New Cloud Phone Setup';
if (isMultiSite) scenarioLabel += ` — ${siteCount} Sites`;

const currentRows = cs.hasProvider
  ? [
      `Provider: ${cs.providerName || 'Unnamed current provider'}`,
      cs.monthlyCost ? `Paying approximately $${cs.monthlyCost}/month` : null,
      ...cs.painPoints,
    ].filter(Boolean)
  : ['No formal cloud phone system in place today', 'Ad-hoc mobile-based call handling'];

const q = body.quantities;
const recommendedRows = [];
recommendedRows.push(`NBN ${q.nbnSpeed}${isMultiSite ? ` at each of ${siteCount} sites` : ''}`);
if (q.lines > 0) recommendedRows.push(`${q.lines * (isMultiSite ? siteCount : 1)} cloud landline${q.lines * siteCount > 1 ? 's' : ''}`);
const hardwareLines = Object.values(q.hardware || {}).filter((h) => h.itemId && h.qty > 0);
for (const h of hardwareLines) {
  const catalogItem = HARDWARE_CATALOG[h.itemId];
  const name = catalogItem ? catalogItem.title : h.itemId;
  recommendedRows.push(`${h.qty}x ${name}${isMultiSite ? ' for central reception' : ''}`);
}
if (q.mobileApps > 0) recommendedRows.push(`${q.mobileApps} mobile app seat${q.mobileApps > 1 ? 's' : ''} (Ringotel)`);
if (q.number1300) recommendedRows.push(isMultiSite ? `Dedicated number for each of ${siteCount} sites` : 'Dedicated 1300 number');
recommendedRows.push('TrueTel local Melbourne support team');

const totalIncGst = body.pricing.totalIncGst;
const monthlySavings = cs.hasProvider && cs.monthlyCost
  ? Math.round((cs.monthlyCost - totalIncGst) * 100) / 100
  : null;

return [{
  json: {
    ...body,
    isMultiSite,
    siteCount,
    scenarioType,
    scenarioLabel,
    currentRows,
    recommendedRows,
    monthlySavings,
  },
}];

const d = $json;
const cs = d.currentSetup;

const scenarioContext = d.scenarioType === 'switching'
  ? `This client is SWITCHING from an existing provider (${cs.providerName || 'unnamed'}), currently paying about $${cs.monthlyCost || 'an unknown amount'}/month. Their stated pain points: ${cs.painPoints.join(', ') || 'none specified'}. ${d.monthlySavings !== null ? `Switching saves them approximately $${d.monthlySavings}/month.` : ''} Hero stats MUST lean into competitive advantage over their current provider — savings, reliability, continuity (e.g. number retention) — not generic feature bullets.`
  : `This is a NEW installation — the client has no existing formal phone system. Hero stats should emphasise speed to live, support quality, and the value of the bundle, since there is no "switching" story to tell.`;

const scaleContext = d.isMultiSite
  ? `This is a MULTI-SITE consolidation across ${d.siteCount} locations onto one centrally managed platform (the same shape as TrueTel's real 12-college deal) — one of your three hero stats should be about scale/consolidation (e.g. sites connected, single reception view), not just price.`
  : '';

const prompt = `You are writing three short sections of a B2B Cloud Phone sales proposal for TrueTel Solutions, an Australian ISP/MSP. Match the tone of TrueTel's real proposals: direct, outcome-focused, no hype words, one to two sentences per bullet, Australian business register.

Client: ${d.client.companyName}, ${d.discovery.headcount} staff, ${d.discovery.businessStatus === 'relocating' ? 'relocating to a new site' : 'setting up at their current site'}.

${scenarioContext}
${scaleContext}

What TrueTel is proposing: ${d.recommendedRows.join('; ')}.
Monthly investment: $${d.pricing.totalIncGst} inc GST on a ${d.pricing.contractTermMonths}-month term.

Return ONLY valid JSON, no markdown, no commentary, matching exactly this shape:
{
  "executiveSummary": "one or two sentences, <= 240 characters",
  "keyOutcomes": ["<=6 bullets, each <=90 characters"],
  "heroStats": [
    {"value": "...", "label": "..."},
    {"value": "...", "label": "..."},
    {"value": "...", "label": "..."}
  ]
}

STRICT RULES FOR heroStats — these are read out of a stat tile, like a scoreboard, not a sentence:
- "value" is ONLY a bare number, currency amount, percentage, or short duration — nothing else. Valid examples: "30%", "$140", "5 days", "100%", "24/7", "12". Invalid: "Lower Monthly Cost", "Guaranteed", any sentence or phrase — those belong in "label", never in "value".
- "value" is 1-8 characters, contains no spaces except inside a duration like "5 days", and no full words describing a benefit.
- "label" is a short caption under the number, max 24 characters, e.g. "Saved per month", "Numbers retained", "Sites connected".
- heroStats must be the three most compelling, TRUE numbers for THIS deal, derived only from the figures given above — never invented. If switching, at least one stat should directly compare to their current spend or guarantee continuity. If new install, favour speed-to-live and support-quality stats. If multi-site, at least one stat should reflect the number of sites or the "one platform" consolidation story.`;

return [{
  json: {
    ...d,
    openAiRequest: {
      model: 'gpt-4o-mini',
      max_tokens: 700,
      temperature: 0.4,
      messages: [{ role: 'user', content: prompt }],
    },
  },
}];

const d = $('Build AI Prompt').item.json;
const aiResponse = $json;

function fallbackStats(d) {
  if (d.isMultiSite) {
    return [
      { value: `${d.siteCount}`, label: 'Sites connected' },
      { value: '1', label: 'Central reception view' },
      { value: `${d.pricing.contractTermMonths}mo`, label: 'Term' },
    ];
  }
  if (d.scenarioType === 'switching' && d.monthlySavings !== null && d.monthlySavings > 0) {
    return [
      { value: `$${Math.abs(d.monthlySavings)}`, label: 'Saved per month' },
      { value: `${d.quantities.lines || 1}`, label: 'Lines migrated' },
      { value: '100%', label: 'Numbers retained' },
    ];
  }
  return [
    { value: `${d.discovery.headcount}`, label: 'Staff covered' },
    { value: `${d.pricing.contractTermMonths}mo`, label: 'Term' },
    { value: '24/7', label: 'Support' },
  ];
}

const cap = (s, n) => (typeof s === 'string' ? s.slice(0, n) : '');

// A "value" is a scoreboard number, not a sentence: short, <=8 chars, at most
// one space (so "5 days" passes but "Lower Monthly Cost" fails). This is the
// exact shape check that catches the model returning a label-shaped phrase
// where the number belongs — the bug that showed up as blank/wrong hero
// stats in production.
function isValidStatValue(v) {
  if (typeof v !== 'string') return false;
  const trimmed = v.trim();
  if (!trimmed || trimmed.length > 8) return false;
  if ((trimmed.match(/ /g) || []).length > 1) return false;
  return true;
}

const fallback = fallbackStats(d);

let parsed = null;
try {
  const raw = aiResponse.choices?.[0]?.message?.content || '';
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = null;
}

const heroStats = [0, 1, 2].map((i) => {
  const candidate = parsed?.heroStats?.[i];
  if (candidate && isValidStatValue(candidate.value) && typeof candidate.label === 'string' && candidate.label.trim()) {
    return { value: cap(candidate.value.trim(), 8), label: cap(candidate.label.trim(), 24) };
  }
  return fallback[i]; // per-stat fallback — one bad stat doesn't discard the other two good ones
});

const narrative = {
  executiveSummary: cap(parsed?.executiveSummary, 240) || `TrueTel proposes a Cloud Phone solution for ${d.client.companyName}.`,
  keyOutcomes: Array.isArray(parsed?.keyOutcomes) && parsed.keyOutcomes.length
    ? parsed.keyOutcomes.slice(0, 6).map((s) => cap(s, 90))
    : d.recommendedRows.slice(0, 6),
  heroStats,
};

return [{ json: { ...d, narrative } }];

